<?php
namespace App\Http\Controllers;
use App\Models\{Entry,Inquiry,Setting,Media,User,Attachment,Quotation};
use App\Services\QuoteTotals;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,Gate,Hash,Storage,DB};
use Illuminate\Validation\Rule;
class AdminController extends Controller{
 public function login(){return view('admin.login');}
 public function authenticate(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);if(Auth::attempt($d)){if(!in_array($r->user()->role,['admin','staff'],true)){Auth::logout();abort(403);}$r->session()->regenerate();return redirect('/admin');}return back()->withErrors(['email'=>'Invalid credentials.'])->onlyInput('email');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/admin/login');}
 public function dashboard(Request $r){$r->validate(['q'=>'nullable|string|max:100','status'=>['nullable',Rule::in(Inquiry::STATUSES)]]);$inquiries=Inquiry::query()->when($r->q,fn($q)=>$q->where(fn($q)=>$q->where('reference','like','%'.$r->q.'%')->orWhere('name','like','%'.$r->q.'%')->orWhere('phone','like','%'.$r->q.'%')))->when($r->status,fn($q)=>$q->where('status',$r->status))->latest()->paginate(20)->withQueryString();$counts=Inquiry::selectRaw('status, count(*) as count')->groupBy('status')->pluck('count','status');return view('admin.dashboard',compact('inquiries','counts'));}
 public function inquiry(Inquiry $inquiry){Gate::authorize('view',$inquiry);$inquiry->load(['attachments','histories','quotations']);return view('admin.inquiry',['inquiry'=>$inquiry,'staff'=>User::whereIn('role',['admin','staff'])->get()]);}
 public function updateInquiry(Request $r,Inquiry $inquiry){Gate::authorize('update',$inquiry);$d=$r->validate(['status'=>['required',Rule::in(Inquiry::STATUSES)],'notes'=>'nullable|string|max:20000','assigned_to'=>['nullable',Rule::exists('users','id')->whereIn('role',['admin','staff'])]]);DB::transaction(function()use($d,$inquiry,$r){if($inquiry->status!==$d['status'])$inquiry->histories()->create(['status'=>$d['status'],'user_id'=>$r->user()->id]);$inquiry->update($d);});return back()->with('success','Inquiry updated.');}
 public function download(Attachment $attachment){Gate::authorize('view',$attachment->inquiry);return Storage::disk('local')->download($attachment->path,$attachment->name,['X-Content-Type-Options'=>'nosniff','Content-Security-Policy'=>"default-src 'none'; sandbox"]);}
 public function quote(Request $r,Inquiry $inquiry){Gate::authorize('update',$inquiry);$d=$r->validate(['items'=>'required|array|min:1|max:30','items.*.description'=>'required|string|max:300','items.*.quantity'=>'required|integer|between:1,100000','items.*.price'=>'required|numeric|between:0,10000000|decimal:0,2','discount'=>'required|numeric|between:0,10000000|decimal:0,2','delivery'=>'required|numeric|between:0,10000000|decimal:0,2','installation'=>'required|numeric|between:0,10000000|decimal:0,2','tax_rate'=>'required|numeric|between:0,100','valid_until'=>'required|date|after_or_equal:today','terms'=>'required|string|max:5000']);$tax=Setting::get('tax_enabled')==='1'?(float)$d['tax_rate']:0;$totals=QuoteTotals::calculate($d['items'],QuoteTotals::cents($d['discount']),QuoteTotals::cents($d['delivery']),QuoteTotals::cents($d['installation']),$tax);DB::transaction(function()use($inquiry,$totals,$d,$r){$inquiry->quotations()->create($totals+['valid_until'=>$d['valid_until'],'terms'=>$d['terms']]);$inquiry->update(['status'=>'Quoted']);$inquiry->histories()->create(['status'=>'Quoted','user_id'=>$r->user()->id]);});return back()->with('success','Quotation created.');}
 public function printQuote(Quotation $quotation,string $locale){Gate::authorize('view',$quotation->inquiry);app()->setLocale($locale);return view('admin.print',compact('quotation'));}
 public function content(Request $r,string $type){$entries=Entry::where('type',$type)->orderBy('sort_order')->get();$edit=$r->filled('edit')?Entry::where('type',$type)->findOrFail($r->edit):null;return view('admin.content',compact('type','entries','edit'));}
 public function saveEntry(Request $r,string $type){$entry=$r->filled('id')?Entry::where('type',$type)->findOrFail($r->id):new Entry(['type'=>$type]);$d=$r->validate(['slug'=>['required','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/','max:120',Rule::unique('entries','slug')->ignore($entry->id)],'title_ar'=>'required|string|max:200','title_en'=>'required|string|max:200','body_ar'=>'required|string|max:20000','body_en'=>'required|string|max:20000','seo_ar'=>'nullable|string|max:170','seo_en'=>'nullable|string|max:170','category'=>'nullable|string|max:100','options'=>'nullable|string|max:2000','price'=>'nullable|numeric|min:0|max:10000000','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:5120','sort_order'=>'required|integer|between:0,10000']);$meta=$entry->meta??[];$meta['seo']=['ar'=>$d['seo_ar']??'','en'=>$d['seo_en']??''];$meta['category']=$d['category']??'';$meta['options']=$d['options']??'';$meta['price']=$r->boolean('price_verified')?($d['price']??null):null;if($r->hasFile('image'))$meta['image']='storage/'.$r->file('image')->store('portfolio','public');$entry->fill(['slug'=>$d['slug'],'title'=>['ar'=>$d['title_ar'],'en'=>$d['title_en']],'body'=>['ar'=>$d['body_ar'],'en'=>$d['body_en']],'meta'=>$meta,'sort_order'=>$d['sort_order'],'published'=>$r->boolean('published'),'featured'=>$r->boolean('featured')])->save();return redirect('/admin/content/'.$type)->with('success','Content saved.');}
 public function deleteEntry(Entry $entry){$entry->delete();return back()->with('success','Content deleted.');}
 public function settings(){return view('admin.settings',['values'=>Setting::pluck('value','key')]);}
 public function saveSettings(Request $r){$keys=['brand_name','city','address','phone','whatsapp','email','notification_email','map_url','opening_hours','service_areas','social_facebook','social_instagram','seo_title_ar','seo_title_en','seo_description_ar','seo_description_en','analytics_id'];$rules=array_fill_keys($keys,'nullable|string|max:1000');foreach(['email','notification_email'] as $key)$rules[$key]='nullable|email|max:190';foreach(['map_url','social_facebook','social_instagram'] as $key)$rules[$key]='nullable|url:http,https|max:1000';$rules['whatsapp']='nullable|regex:/^[0-9]{7,15}$/';$rules['phone']='nullable|regex:/^[+0-9 ()-]{7,30}$/';$rules['analytics_id']='nullable|regex:/^G-[A-Z0-9]+$/';$d=$r->validate($rules+['logo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048']);foreach($keys as $key)Setting::updateOrCreate(['key'=>$key],['value'=>$d[$key]??'']);Setting::updateOrCreate(['key'=>'tax_enabled'],['value'=>$r->boolean('tax_enabled')?'1':'0']);if($r->hasFile('logo'))Setting::updateOrCreate(['key'=>'logo'],['value'=>'storage/'.$r->file('logo')->store('branding','public')]);return back()->with('success','Settings saved.');}
 public function media(){return view('admin.media',['media'=>Media::latest()->get()]);}
 public function saveMedia(Request $r){$d=$r->validate(['file'=>'required|file|mimes:jpg,jpeg,png,webp,mp4,webm|max:51200','poster'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:5120','caption_ar'=>'required|string|max:250','caption_en'=>'required|string|max:250','alt_ar'=>'required|string|max:250','alt_en'=>'required|string|max:250']);$f=$r->file('file');$video=str_starts_with($f->getMimeType(),'video/');if($video&&!$r->hasFile('poster'))return back()->withErrors(['poster'=>'Video requires a poster image.'])->withInput();$disk=$r->boolean('approved')?'public':'local';$prefix=$disk==='public'?'storage/':'';Media::create(['disk'=>$disk,'path'=>$prefix.$f->store('portfolio',$disk),'poster'=>$r->hasFile('poster')?$prefix.$r->file('poster')->store('portfolio',$disk):null,'kind'=>$video?'video':'image','caption'=>['ar'=>$d['caption_ar'],'en'=>$d['caption_en']],'alt'=>['ar'=>$d['alt_ar'],'en'=>$d['alt_en']],'approved'=>$r->boolean('approved')]);return back()->with('success','Media uploaded.');}
 public function updateMedia(Request $r,Media $media){$d=$r->validate(['caption_ar'=>'required|string|max:250','caption_en'=>'required|string|max:250','alt_ar'=>'required|string|max:250','alt_en'=>'required|string|max:250']);if($media->approved!==$r->boolean('approved')){$newDisk=$r->boolean('approved')?'public':'local';foreach(['path','poster'] as $field){if(!$media->$field)continue;$oldDisk=$media->disk;$oldPath=$oldDisk==='public'?preg_replace('#^storage/#','',$media->$field):$media->$field;if(str_starts_with($media->$field,'media/'))continue;$newPath='portfolio/'.\Illuminate\Support\Str::uuid().'.'.pathinfo($oldPath,PATHINFO_EXTENSION);Storage::disk($newDisk)->put($newPath,Storage::disk($oldDisk)->readStream($oldPath));Storage::disk($oldDisk)->delete($oldPath);$media->$field=($newDisk==='public'?'storage/':'').$newPath;}if(!str_starts_with($media->path,'media/'))$media->disk=$newDisk;}$media->update(['caption'=>['ar'=>$d['caption_ar'],'en'=>$d['caption_en']],'alt'=>['ar'=>$d['alt_ar'],'en'=>$d['alt_en']],'approved'=>$r->boolean('approved')]);return back()->with('success','Media updated.');}
 public function mediaFile(Media $media){abort_unless($media->disk==='local',404);return Storage::disk('local')->response($media->path,null,['X-Content-Type-Options'=>'nosniff']);}
 public function mediaPoster(Media $media){abort_unless($media->disk==='local'&&$media->poster,404);return Storage::disk('local')->response($media->poster,null,['X-Content-Type-Options'=>'nosniff']);}
 public function users(){return view('admin.users',['users'=>User::all()]);}
 public function saveUser(Request $r){$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|unique:users,email','password'=>'required|string|min:12|confirmed','role'=>'required|in:admin,staff']);User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password']),'role'=>$d['role']]);return back()->with('success','Account created.');}
}
